function persist(){try{localStorage.setItem(KEY,JSON.stringify(storage));persistent=true;return true;}catch{if(persistent)toast('Browser storage is unavailable. Changes will last for this session.');persistent=false;return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function navigation(){
  $('#navigation').innerHTML=Object.entries(labels).map(([id,[i,label]])=>`<button class="nav-item ${page===id?'active':''}" data-nav="${id}" aria-label="${label}" ${page===id?'aria-current="page"':''}>${icon(i)}<span class="nav-label">${label}</span><span class="nav-short">${({explore:'Explore',shortlist:'Shortlist',compare:'Compare',workspace:'Studio',sources:'Data'})[id]}</span>${['shortlist','compare'].includes(id)&&storage[id==='shortlist'?'saved':'compare'].length>0?`<span class="nav-count">${storage[id==='shortlist'?'saved':'compare'].length}</span>`:''}</button>`).join('');
  $('#profile-label').textContent=storage.profile?`My profile · ${persistent?'local':'session'}`:'My profile';
}
function card(p,tracking=false){
  const s=applicationStatus(p),a=assess(p,storage.profile),index=programs.indexOf(p),mark=p.university.split(/[\s&]+/).filter(w=>!['of','the','and'].includes(w.toLowerCase())).map(w=>w[0]).join('').slice(0,4);
  const count=(storage.tasks[p.id]||[]).length;
  return `<article class="program-card" data-program="${p.id}"><div class="card-heading"><div class="uni-mark ${['','blue','gold','red'][index%4]}" aria-hidden="true">${e(mark)}</div><div class="card-title"><button class="title-button" data-detail="${p.id}">${e(p.title)} <span style="font-size:9px;font-weight:400;color:#87917f">Master’s</span></button><p class="university-name">${e(p.university)}</p></div><button class="save-button ${storage.saved.includes(p.id)?'saved':''}" data-save="${p.id}" aria-label="${storage.saved.includes(p.id)?'Remove from':'Add to'} shortlist: ${e(p.title)}" aria-pressed="${storage.saved.includes(p.id)}">${icon('bookmark')}</button></div><div class="location-row">${icon('pin')}${e(p.city)}, ${e(p.country)}</div><div class="card-tags">${p.tags.slice(0,3).map(t=>`<span class="tag">${e(t)}</span>`).join('')}</div><div class="card-meta"><span>${icon('clock')}${e(p.duration)}</span><span>${icon('book')}${e(p.language)}</span><span>${e(p.mode)}</span></div><div class="card-footer"><span class="status ${s.key}"><span class="tiny-dot"></span>${s.label}</span><button class="card-link" data-detail="${p.id}">View programme ${icon('arrow')}</button></div><div class="card-action-line"><label class="compare-check"><input type="checkbox" data-compare="${p.id}" ${storage.compare.includes(p.id)?'checked':''} aria-label="Compare ${e(p.title)} at ${e(p.university)}">Compare</label>${storage.profile?`<span class="fit-label ${a.key}">${e(a.label)}</span>`:`<span>${p.registry?'Registry identity · admissions unreviewed':'Official programme source linked'}</span>`}</div>${tracking?`<div class="tracking-row"><label class="form-field" style="margin:0">Application status<select data-track="${p.id}">${['Researching','Preparing','Submitted','Offer received','Not proceeding'].map(t=>`<option ${storage.tracking[p.id]===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="progress-track"><span style="width:${count/CHECKLIST.length*100}%"></span></div><span class="progress-label">${count} of ${CHECKLIST.length} preparation steps complete · <button class="text-link" data-detail="${p.id}" data-tab="notes">Open checklist</button></span></div>`:''}</article>`;
}
function empty(title,description,action='explore',button='Explore programmes'){return `<div class="empty-state"><div class="empty-icon">${icon('globe')}</div><h2>${title}</h2><p>${description}</p><button class="button" data-nav="${action}">${button} ${icon('arrow')}</button></div>`;}
function tray(){document.querySelector('.compare-tray')?.remove();if(storage.compare.length&&!['compare','welcome'].includes(page)){const el=document.createElement('div');el.className='compare-tray';el.innerHTML=`<span><strong>${storage.compare.length}</strong> programme${storage.compare.length>1?'s':''} selected</span><button class="button small" data-nav="compare">Compare ${icon('arrow')}</button><button data-action="clear-compare" aria-label="Clear comparison">${icon('close')}</button>`;document.body.append(el);}}
function pageHead(eyebrow,title,description,action=''){return `<header class="page-header"><p class="eyebrow">${eyebrow}</p><div class="page-header-row"><h1>${title}</h1>${action}</div><p>${description}</p></header>`;}
function setPopover(name,open){
  for(const [id,action] of [['workspace-menu','toggle-menu'],['filter-panel','toggle-filters']]){
    const panel=$('#'+id),active=id===name&&open;if(panel)panel.hidden=!active;
    document.querySelector(`[data-action="${action}"]`)?.setAttribute('aria-expanded',String(active));
  }
  if(name==='filter-panel'&&open)setResults(false);
}
function renderPage(rebuild=false){
  rememberStudio();
  page=location.hash.slice(1)||'explore';if(!names[page]||page==='welcome')page='explore';
  $('#detail-dialog').close();document.body.classList.remove('detail-open');setPopover('',false);
  document.body.classList.toggle('workspace-mode',page!=='explore');
  const sidePanel=['shortlist','compare'].includes(page);document.body.classList.toggle('side-panel-mode',sidePanel);
  document.body.classList.toggle('comparison-panel-mode',page==='compare');
  navigation();$('#main').setAttribute('aria-label',names[page]);
  if(rebuild||!$('.atlas-stage')){map?.destroy();map=null;renderExplore();}
  $('.workspace-sheet')?.remove();$('.atlas-stage').inert=page!=='explore'&&!sidePanel;setResults(resultsOpen&&page==='explore');
  if(page!=='explore'){
    const sheet=document.createElement('section');sheet.className='workspace-sheet'+(sidePanel?' workspace-drawer '+page+'-drawer':page==='workspace'?' studio-workspace':'');sheet.setAttribute('aria-label',names[page]);
    sheet.innerHTML=`<button class="workspace-dismiss" data-nav="explore" aria-label="Back to the map">${icon('close')}</button><div id="workspace-screen"></div>`;$('#screen').append(sheet);
    if(page==='shortlist')renderShortlist();else if(page==='compare')renderCompare();else if(page==='workspace')renderWorkspace();else renderSources();
  }
  tray();
}
function setResults(open){if(open&&$('#filter-panel')&&!$('#filter-panel').hidden)return;if(!open){clusterIds=null;resultsObserver?.disconnect();}resultsOpen=open;const drawer=$('#map-results');if(!drawer)return;drawer.hidden=!open;document.body.classList.toggle('results-open',open);const button=$('.browse-button');button?.setAttribute('aria-expanded',open);if(open)updateResults();}
const activeCatalogue=()=>catalogueMode==='institutions'?institutions:programs;
const filteredLocations=()=>catalogueMode==='institutions'?filterInstitutions(institutions,filters):filterPrograms(programs,filters,storage.profile);
async function loadInstitutionIndex(){
  institutionPromise??=fetch('data/institutions.json').then(r=>{if(!r.ok)throw Error('Directory unavailable');return r.json();}).catch(error=>{institutionPromise=null;throw error;});
  institutions=await institutionPromise;return institutions;
}
async function setCatalogueMode(mode){
  const revision=++modeRevision,select=$('#catalogue-mode');select.disabled=true;
  try{
    if(mode==='institutions'&&!institutionManifest)throw Error('Directory manifest unavailable');
    if(mode==='institutions'&&!institutions.length){
      $('#directory-explanation').hidden=false;$('#directory-explanation').textContent='Loading the institution directory…';
      await loadInstitutionIndex();
    }
    if(revision!==modeRevision)return;
    catalogueMode=mode;clusterIds=null;resultsLimit=50;
    Object.assign(filters,{query:'',country:'',field:'',open:false,free:false,fit:'',sort:'name'});
    $('#country').innerHTML='<option value="">All countries & regions</option>'+[...new Set(activeCatalogue().map(p=>p.country))].sort().map(country=>`<option>${e(country)}</option>`).join('');
    syncFilters();updateResults();
  }catch{syncFilters();toast('The directory could not load. Programme discovery remains available.');}
  finally{select.disabled=false;}
}
function openInstitution(id){
  const p=institutions.find(p=>p.id===id);if(!p||!institutionManifest)return;
  detailId=id;const d=$('#detail-dialog');d.innerHTML=institutionDetail(p,institutionManifest,icon);if(!d.open)d.show();document.body.classList.add('detail-open');d.scrollTop=0;
  if(page==='explore')map?.focus(p);d.querySelector('.dialog-close').focus({preventScroll:true});
}
function renderExplore(){
  resultsObserver?.disconnect();resultsKey='';
  $('#screen').innerHTML=atlasTemplate(programs,filters,storage.profile,icon);
  $('#results').addEventListener('scroll',()=>{const list=$('#results');if(list.scrollTop+list.clientHeight>=list.scrollHeight-120)loadNextResults();},{passive:true});
  $('#search').addEventListener('focus',()=>{clusterIds=null;setPopover('',false);$('#detail-dialog').close();setResults(true);});
  $('#search').addEventListener('input',ev=>{filters.query=ev.target.value;clusterIds=null;resultsLimit=50;setResults(true);updateResults();});
  $('#field').onchange=ev=>{filters.field=ev.target.value;clusterIds=null;resultsLimit=50;setResults(true);syncFilters();updateResults();};
  $('#country').onchange=ev=>{filters.country=ev.target.value;clusterIds=null;resultsLimit=50;setResults(true);updateResults();if(filters.country)map?.focusCountry(activeCatalogue().filter(p=>p.country===filters.country));};
  $('#sort').onchange=ev=>{filters.sort=ev.target.value;resultsLimit=50;updateResults();};
  $('#catalogue-mode').onchange=ev=>setCatalogueMode(ev.target.value);
  if($('#fit'))$('#fit').onchange=ev=>{filters.fit=ev.target.value;clusterIds=null;setResults(true);updateResults();};
  syncFilters();updateResults();setResults(resultsOpen&&page==='explore');
  const holder=$('.map-panel');
  createMap(holder,filteredLocations(),id=>id.startsWith('ror-')?openInstitution(id):openDetail(id),items=>{clusterIds=new Set(items.map(p=>p.id));resultsLimit=50;$('#detail-dialog').close();setResults(true);}).then(m=>{if(holder.isConnected){map=m;map.update(filteredLocations());}else m.destroy();}).catch(()=>{if(holder.isConnected)holder.querySelector('.map-error').hidden=false;});
}
function syncFilters(){
  if(!$('#field'))return;
  const directory=catalogueMode==='institutions';
  $('#catalogue-mode').value=catalogueMode;
  document.querySelectorAll('.programme-only').forEach(el=>el.hidden=directory);
  $('#directory-explanation').hidden=!directory;
  $('#directory-explanation').textContent='ROR education institutions. Master’s availability and admission rules require separate verification.';
  $('#profile-review-field').hidden=directory||!storage.profile;
  $('#sort option[value=deadline]').disabled=directory;
  $('#sort option[value=deadline]').hidden=directory;
  $('#sort option[value=title]').hidden=directory;
  $('#sort option[value=title]').disabled=directory;
  $('#sort').disabled=directory;
  $('#sort option[value=name]').textContent=directory?'Institution A–Z':'University A–Z';
  $('#sort').value=filters.sort;
  $('#search').placeholder=directory?'Search institutions':'Search programmes';
  $('#search').setAttribute('aria-label',directory?'Search institutions':'Search programmes');
  $('.filter-trigger').setAttribute('aria-label',directory?'Filter institutions':'Filter programmes');
  $('#sort').setAttribute('aria-label',directory?'Sort institutions':'Sort programmes');
  $('#map-results').setAttribute('aria-label',directory?'Institution results':'Programme results');
  const browse=$('.browse-button');
  if(browse){browse.innerHTML=icon('list')+(directory?'Browse institutions':'Browse programmes');browse.setAttribute('aria-label',directory?'Browse institutions':'Browse programmes');}
  $('#catalogue-scope').hidden=!directory;
  $('#catalogue-scope').textContent=`Institution directory · ${institutions.length.toLocaleString('en')} indexed · degree availability not verified`;
  $('.directory-attribution')?.remove();
  if(directory){
    const credit=document.createElement('span');credit.className='directory-attribution';
    credit.innerHTML=' · <a href="https://ror.org/" target="_blank" rel="noopener noreferrer">ROR</a> · <a href="https://www.geonames.org/" target="_blank" rel="noopener noreferrer">GeoNames</a>';
    $('.map-attribution').append(credit);
  }
  if($('#fit'))$('#fit').value=filters.fit;
  $('#field').value=filters.field;$('#country').value=filters.country;$('#search').value=filters.query;
  document.querySelectorAll('[data-filter]').forEach(b=>{const on=filters[b.dataset.filter];b.classList.toggle('active',on);b.setAttribute('aria-pressed',on);});
  document.querySelectorAll('[data-quick]').forEach(b=>{const on=filters.field===b.dataset.quick;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on);});
}
function resultsProgress(){
  const shown=Math.min(resultsLimit,resultsData.length),noun=catalogueMode==='institutions'?'institutions':'programmes';
  $('.results-pagination').hidden=!resultsData.length;
  $('#results-progress').textContent=`${shown.toLocaleString('en')} of ${resultsData.length.toLocaleString('en')} ${noun}`;
}
function watchResultsEnd(){
  resultsObserver?.disconnect();const list=$('#results'),end=$('#results-end');
  if(!end||!('IntersectionObserver' in window))return;
  resultsObserver=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting&&entry.target===$('#results-end')))loadNextResults();},{root:list,rootMargin:'0px 0px 120px 0px'});
  resultsObserver.observe(end);
}
function resultsEnd(){return resultsLimit<resultsData.length?'<div id="results-end" class="results-sentinel" aria-hidden="true"></div>':'';}
function loadNextResults(){
  const list=$('#results');
  if(!list||!resultsOpen||page!=='explore'||$('#map-results').hidden||!list.clientHeight||resultsLimit>=resultsData.length)return;
  resultsObserver?.disconnect();$('#results-end')?.remove();
  const next=resultsData.slice(resultsLimit,resultsLimit+50);resultsLimit+=next.length;
  list.insertAdjacentHTML('beforeend',next.map(p=>catalogueMode==='institutions'?institutionCard(p,icon):card(p)).join('')+resultsEnd());
  resultsProgress();watchResultsEnd();
}
function updateResults(){
  const list=$('#results');if(!list)return;
  const directory=catalogueMode==='institutions',noun=directory?'institution':'programme';
  const active=filters.field||filters.country||filters.open||filters.free||filters.fit;$('.filter-indicator').hidden=!active;
  const locations=filteredLocations();resultsData=clusterIds?locations.filter(p=>clusterIds.has(p.id)):locations;
  const key=JSON.stringify([catalogueMode,filters,clusterIds?[...clusterIds].sort():null,filters.fit?storage.profile:null]),reset=key!==resultsKey;
  if(reset){resultsLimit=50;resultsKey=key;}
  const scrollTop=reset?0:list.scrollTop;resultsObserver?.disconnect();
  $('#result-count').textContent=`${resultsData.length.toLocaleString('en')} ${noun}${resultsData.length===1?'':'s'}`;
  $('#visible-count').textContent=$('#result-count').textContent;$('#map-results h2').textContent=directory?'Institutions':'Programmes';
  list.dataset.order=!directory&&filters.sort==='name'?'university':'programme';list.setAttribute('aria-label',directory?'Institution list':'Programme list');
  list.innerHTML=resultsData.length?resultsData.slice(0,resultsLimit).map(p=>directory?institutionCard(p,icon):card(p)).join('')+resultsEnd():empty('A new direction?',`No ${noun}s match these filters. Broaden your search.`,'explore','Clear filters');
  list.scrollTo({top:scrollTop,behavior:'instant'});resultsProgress();watchResultsEnd();
  if(!resultsData.length)$('#results [data-nav]').dataset.action='reset';map?.update(locations);
}
function renderShortlist(){const list=programs.filter(p=>storage.saved.includes(p.id));$('#workspace-screen').innerHTML=pageHead('YOUR WORKSPACE','My shortlist','Keep the programmes that spark your curiosity. Track your next step, one application at a time.',`<button class="button secondary" data-action="export-workspace">${icon('download')}Download Excel .xlsx</button>`)+`<div class="shortlist-grid">${list.length?list.map(p=>card(p,true)).join(''):empty('Start with a little curiosity.','Save programmes using the bookmark icon. Your notes, preparation checklist and application status stay in this browser.')}</div><p class="explorer-note">Saved in this browser. Excel includes your programme activity, notes and saved drafts. Recovery backups are available in Data & methodology.</p>`;}
function renderCompare(){
  const list=storage.compare.map(id=>programs.find(p=>p.id===id)).filter(Boolean);
  let body=empty('See the differences, side by side.','Select up to three programmes with the Compare checkbox.');
  if(list.length){const rows=comparisonRows(storage.profile).map(([label,value])=>[label,p=>e(value(p)).replaceAll('\n','<br>')]);rows.push(['Official sources',p=>p.sources.map(s=>`<a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.label)} ↗</a>`).join('<br>')]);
    body=`<p class="comparison-hint">Scroll sideways to view every programme. The field labels stay in view.</p><div class="comparison-wrap" tabindex="0" aria-label="Programme comparison table" style="--table-width:${140+list.length*190}px"><table class="comparison-table"><thead><tr><th scope="col">Your options</th>${list.map(p=>`<th scope="col">${e(p.title)}<p>${e(p.university)}</p><button class="text-link" data-remove-compare="${p.id}">Remove</button></th>`).join('')}</tr></thead><tbody>${rows.map(([label,value])=>`<tr><th scope="row">${label}</th>${list.map(p=>`<td>${value(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="comparison-bottom"><button class="button secondary small" data-action="download-compare">${icon('download')}Download Excel .xlsx</button><span>Fees retain their applicant category and year. Confirm current requirements with the university.</span></div>`;
  }
  $('#workspace-screen').innerHTML=pageHead('YOUR WORKSPACE','Compare programmes','Compare up to three programmes, with their official sources.')+body;
}
function rememberStudio(){if($('#email-form')&&draft)draft.fields=Object.fromEntries(new FormData($('#email-form')));}
function studioProgramme(){return programs.find(p=>p.id===(studioId||draft?.id))||programs.find(p=>storage.saved.includes(p.id))||programs[0];}
function renderWorkspace(){
  const p=studioProgramme();studioId=p.id;
  if(!draft||draft.id!==p.id){const saved=storage.drafts[p.id],fields={degree:storage.profile?.degree||'',recipient:saved?.purpose==='research'?'':p.contact?.name||'Admissions team',...saved?.fields,purpose:saved?.purpose||'admissions',recipientEmail:saved?.recipientEmail??p.contact?.email??''};draft={...(saved||makeEmail(p,fields)),id:p.id,fields};}
  $('#workspace-screen').innerHTML=pageHead('YOUR WORKSPACE','Application studio','Prepare your application, check the evidence and draft a focused enquiry.')+studioTemplate(programs,p,{tab:studioTab,tasks:storage.tasks[p.id]||[],notes:storage.notes[p.id]||'',draft,savedDraft:storage.drafts[p.id],guides:guidance,profile:storage.profile,persistent,icon});
  $('#email-programme').onchange=ev=>{rememberStudio();studioId=ev.target.value;draft=null;renderWorkspace();};
  if($('#studio-note'))$('#studio-note').oninput=ev=>{storage.notes[p.id]=ev.target.value;persist();};
  if(studioTab==='enquiry'){
    generateDraft(p,false);
    $('#email-form').onsubmit=ev=>{ev.preventDefault();generateDraft(p,true);toast('Draft ready. Check the details before using it.');};
    $('#enquiry-purpose').onchange=ev=>{if(ev.target.value==='research'){const form=$('#email-form');form.elements.recipient.value='';form.elements.recipientEmail.value='';}rememberStudio();renderWorkspace();toast('Purpose changed. Create a new draft or revise your existing message.');};
    $('#email-form').oninput=()=>{rememberStudio();$('#open-email').disabled=!validRecipient();updateDraftReview();};
    $('#email-draft').oninput=ev=>{draft.body=ev.target.value;updateDraftReview();};
    $('#email-subject').oninput=ev=>{draft.subject=ev.target.value;updateDraftReview();};
  }
}
function validRecipient(){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test($('#email-form')?.elements.recipientEmail.value.trim()||'');}
function updateDraftReview(){
  const result=reviewDraft(draft.subject,draft.body),panel=$('#draft-review');if(!panel)return;
  panel.classList.toggle('needs-details',result.issues.length>0);
  panel.innerHTML=`<strong>Draft review · ${result.words} words</strong>${result.issues.length?`<ul>${result.issues.map(i=>`<li>${e(i)}</li>`).join('')}</ul>`:'<p>No placeholders detected. Verify the recipient and programme instructions before sending.</p>'}`;
  const saved=storage.drafts[draft.id];$('#draft-save-status').textContent=saved?(draftMatches(saved,draft)?'Local copy saved':'Unsaved changes'):'Not saved';
}
function generateDraft(p,regenerate=true){
  const fields=Object.fromEntries(new FormData($('#email-form')));
  if(regenerate||!draft||draft.id!==p.id)draft={...makeEmail(p,fields),id:p.id,fields};else draft.fields=fields;
  $('#email-subject').value=draft.subject;$('#email-draft').value=draft.body;$('#open-email').disabled=!validRecipient();
  $('#email-contact').innerHTML=p.contact?`Recorded programme contact: <strong>${e(p.contact.name)}</strong> · <a href="${e(p.contact.source)}" target="_blank" rel="noopener noreferrer">Verify ${e(p.contact.email)} ↗</a>. Confirm the recipient’s role. This address is not evidence of research supervision availability.`:'No contact email is recorded. Find the appropriate recipient on the official page.';
  updateDraftReview();
}
function evidenceDisclosure(p){const labels={linked:'Source-linked',recorded:'Recorded · field source pending',unknown:'Not recorded',stale:'Source needs rechecking'};return `<details class="evidence-disclosure"><summary>Evidence by field</summary><table class="evidence-table"><thead><tr><th>Field</th><th>Evidence</th></tr></thead><tbody>${programmeEvidence(p).map(r=>`<tr><th scope="row">${e(r.label)}</th><td>${labels[r.status]}${r.source?`<a href="${e(r.source)}" target="_blank" rel="noopener noreferrer">Source · ${formatDate(r.checkedAt)} ↗</a>`:''}</td></tr>`).join('')}</tbody></table></details>`;}
function renderSources(){
  const coverage=evidenceCoverage(programs),scope=catalogueSummary(programs);
  const catalogues=`<section class="method-card catalogue-explanation"><h2>Two different catalogues</h2><table class="methodology-table"><tbody><tr><th scope="row">${programs.length} programme / specialisation records</th><td>${scope.programmeSources.toLocaleString('en')} records with programme-page sources and ${scope.registry.toLocaleString('en')} registry-backed degree identities. Admission evidence is partial; registry presence does not prove an available intake. Several records may belong to one institution; this is not a count of universities or a complete global programme list.</td></tr><tr><th scope="row">${institutionManifest?.indexCount.toLocaleString('en')||'Global'} institution records</th><td>Education-type identities from ROR: names, aliases, registry website links and approximate localities. A record does not establish a master's degree, accreditation, admission rules or supervisor availability.</td></tr></tbody></table><p>For example, Nazarbayev University is an institution. Its Political Science and International Relations MA is a programme. The directory helps you discover institutions whose programmes GradAtlas has not yet reviewed.</p><p>Both catalogues are shared research data. My profile, shortlist and personal notes belong to your separate browser-local workspace.</p></section>`;
  const registry=registryManifest?`<section class="method-card"><h2>Registered master's degrees · DUO RIO</h2><p>${scope.registry.toLocaleString('en')} Dutch degree identities from the official HO Opleidingsoverzicht snapshot dated ${e(registryManifest.snapshotDate)}. Active registration dates, recognised degree codes and institution mappings are checked; applications and teaching routes have not been individually reviewed.</p><p>Modes, languages and repeated offerings are grouped by provider and registered degree code. Joint degrees are represented once. Some registered degrees have no current offering in the snapshot. A registration is not an open intake, and the directory of institutions remains a separate catalogue.</p><p>Original international degree names are used where supplied; otherwise legal Dutch names remain. Subject groups are title-based discovery classifications. Coordinates use approximate ROR/GeoNames institution localities, which can differ from the teaching campus.</p><p>${e(registryManifest.attribution)}</p><p>Publisher licence: Creative Commons Attribution; no version was specified in the metadata. Preserve the publisher's <a href="${e(registryManifest.resolvedLicenceUrl)}" target="_blank" rel="noopener noreferrer">licence reference</a>, source credit and GradAtlas transformation notice. Do not relabel it CC0 or assume a particular CC BY version.</p><a class="source-link" href="${e(registryManifest.datasetUrl)}" target="_blank" rel="noopener noreferrer">DUO source dataset & metadata ↗</a><a class="source-link" href="data/programme-registry-manifest.json" download>Download registry provenance ↗</a></section>`:'';
  const reuse=`<details class="evidence-disclosure publication-terms"><summary>Data reuse and publication terms</summary><div class="reuse-body"><table class="methodology-table"><tbody><tr><th scope="row">ROR identity metadata</th><td><a href="https://ror.readme.io/docs/data-dump" target="_blank" rel="noopener noreferrer">CC0 1.0</a> permits copying, modification and redistribution, including commercial use. It does not grant trademark rights or institutional endorsement.</td></tr><tr><th scope="row">GeoNames locality data</th><td><a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a> permits sharing and adaptation, including commercial use. Keep provider credit, source/licence links and modification notices, and do not add restrictions on the licensed data or imply endorsement. Preserve any supplied notices. The directory export carries this provenance.</td></tr><tr><th scope="row">Programme information and source pages</th><td>GradAtlas records short factual information, original summaries and official links. Linked university pages, copied expressions, logos, photographs and external databases retain their own rights and terms. A source link or the software MIT licence does not grant blanket permission to copy those materials.</td></tr><tr><th scope="row">Map and software</th><td><a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener noreferrer">Natural Earth</a> boundaries are public domain. GradAtlas software uses MIT; MapLibre uses BSD-3-Clause and ExcelJS uses MIT. Preserve the applicable software licence notices when redistributing.</td></tr></tbody></table><p>Permission to reuse data is separate from its accuracy. Open licences provide no guarantee that a website, location, fee or admission rule is current or complete. An institution's inclusion does not imply a partnership with GradAtlas.</p><p>Institution downloads include records, source release, attribution, licence links, transformation notes and limitations in one JSON document. Keep this information with reused data. The source index checksum describes the published compact index, not the export wrapper.</p></div></details>`;
  const directory=institutionManifest?`<section class="method-card directory-method"><h2>Global institution directory</h2><p><strong>${institutionManifest.indexCount.toLocaleString('en')}</strong> active education-type ROR records across <strong>${institutionManifest.indexCountryCount}</strong> countries/territories. These are institution identity records; they do not establish master’s availability, accreditation or admissions eligibility. ROR is research-focused and is not an exhaustive university register. Separately identified organisations or campuses are not automatically deduplicated into one university.</p><p>Release ${e(institutionManifest.release)}, published ${e(institutionManifest.releasedAt)}. One point per ROR identifier, at its first valid GeoNames locality. Names, aliases, websites and countries come from this registry; websites have not all been checked for current availability. Locations are approximate cities or administrative areas.</p><p>Institution metadata: <a href="https://ror.org/" target="_blank" rel="noopener noreferrer">ROR</a>, <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noopener noreferrer">CC0 1.0</a>. Geographic data: <a href="https://www.geonames.org/" target="_blank" rel="noopener noreferrer">GeoNames</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. Filtered and reformatted by GradAtlas; upstream legacy licence notes are retained in the manifest.</p><a class="source-link" href="${e(institutionManifest.recordUrl)}" target="_blank" rel="noopener noreferrer">Pinned ROR source release ↗</a><div class="privacy-actions"><button class="button secondary small" data-action="open-directory">Explore institution directory</button><a class="button secondary small" href="data/institution-manifest.json" download="gradatlas-institution-manifest.json">Download provenance manifest</a><button class="button secondary small" data-action="export-institutions">Download directory + licences</button></div><p class="workspace-hint">A pinned bulk import is checked for identifiers, source checksum, filter, coordinates and totals. New master’s programme facts require separate official-source evidence and review; no degree or grade rule is inferred from the directory.</p></section>`:'';
  $('#workspace-screen').innerHTML=pageHead('ABOUT GRADATLAS','Data & methodology','A free research aid created by 7aslann7. Double-check current official instructions before applying.')+`<div class="quality-summary"><div><strong>${programs.length}</strong>programme / specialisation records</div><div><strong>${new Set(programs.map(p=>p.country)).size}</strong>programme countries & regions</div><div><strong>${new Set(programs.flatMap(p=>p.fields)).size}</strong>subject groups</div></div>${catalogues}${directory}${registry}${reuse}<div class="method-grid"><section class="method-card"><h2>Evidence and coverage</h2><p>Each programme has an official source and review date. The evidence table distinguishes source-linked fields, recorded facts awaiting a field-specific source, missing information and older evidence.</p><p>Across nine tracked fields per record: <strong>${coverage.sourceLinked}</strong> have linked sources, <strong>${coverage.recorded}</strong> await field-specific links, and <strong>${coverage.unknown}</strong> are not recorded. These are coverage counts, not an accuracy score.</p><p>A review date describes recorded evidence; it does not certify every admission field or that the page has remained unchanged. Automated validation checks structure, provenance and consistency, not factual accuracy. Evidence older than 90 days is flagged for rechecking; changes can occur sooner.</p><p>The 12 October 2026 targeted audit rechecked the existing dated windows, encoded grade rules, no-tuition claims and legacy IELTS sources. It removed UCL's outdated cycle and corrected fee evidence. Other metadata remains subject to ongoing review.</p><p>Use the programme's own instructions for recognition, course prerequisites, documents, fees, cutoff times and applicant categories. Original grading systems and alternative admission routes are retained. No acceptance probability is calculated.</p><details class="evidence-disclosure" id="programme-sources"><summary>Browse official programme sources</summary><div id="programme-source-records"></div></details><details class="evidence-disclosure"><summary>Application guide sources</summary>${guidance.map(g=>`<div class="source-row"><span><strong>${e(g.title)}</strong><small>${e(g.scope)}</small></span><a href="${e(g.url)}" target="_blank" rel="noopener noreferrer">Official guide ↗</a></div>`).join('')}</details><p>The base map uses simplified <a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener noreferrer">Natural Earth public-domain boundaries</a>, rendered with <a href="https://maplibre.org/" target="_blank" rel="noopener noreferrer">MapLibre</a>. Excel exports are generated locally with MIT-licensed <a href="https://github.com/exceljs/exceljs" target="_blank" rel="noopener noreferrer">ExcelJS</a>.</p><button class="button secondary small" data-action="catalogue">${icon('download')}Download programme catalogue</button></section><section class="method-card"><h2>Your workspace and privacy</h2><p>My profile is optional. The profile, shortlist, comparisons, notes, preparation steps and explicitly saved enquiry drafts stay in this browser's local storage. GradAtlas does not upload them or synchronise them between accounts or devices.</p><p>A shared browser profile on the same device uses the same workspace. Private-browsing storage can disappear when the session ends. Clearing site data can remove the workspace. Download Excel to work with your programme list, notes and preparation status. Use a recovery backup to restore the app on another browser, and remove local data before leaving a shared device.</p><p>A backup contains your profile, notes and saved drafts; keep it private. Hosting access controls do not provide workspace sync. The hosting service receives normal page requests, while application profile fields remain local.</p><div class="privacy-actions"><button class="button secondary small" data-action="export-workspace">${icon('download')}Download workspace Excel</button><button class="button secondary small" data-action="export-recovery">Download recovery backup (.json)</button><label class="button secondary small" for="import-workspace">Restore recovery backup<input class="hidden" type="file" id="import-workspace" accept="application/json,.json"></label><button class="button secondary small" data-action="delete-data">Delete local data</button></div><p style="margin-top:23px">Corrections can be proposed through public GitHub issues and require review before admission facts change. Optional account sync and a maintained review service are planned development stages. Discovery will remain free. Supervisor availability and public reviews need separately verified data.</p></section></div>`;
  $('#workspace-screen').insertAdjacentHTML('beforeend',`<section class="method-card"><h2>Source & feedback</h2><p>Created and maintained by <a href="https://github.com/7aslann7" target="_blank" rel="noopener noreferrer">7aslann7</a>. Explore the source code, report a problem or propose a correction with an official source. Data proposals are reviewed before the catalogue changes; keep personal applicant information out of public reports.</p><div class="privacy-actions"><a class="button secondary small" href="https://github.com/7aslann7/gradatlas" target="_blank" rel="noopener noreferrer">View on GitHub ↗</a><a class="button secondary small" href="https://github.com/7aslann7/gradatlas/issues/new/choose" target="_blank" rel="noopener noreferrer">Give feedback ↗</a></div></section>`);
  const sourceDetails=$('#programme-sources'),sourceRecords=$('#programme-source-records');let sourceLimit=50;
  const renderProgrammeSources=()=>{
    sourceRecords.innerHTML=programs.slice(0,sourceLimit).map(p=>`<div class="source-row"><span><strong>${e(p.university)}</strong><small>${e(p.title)} · ${p.registry?'registry snapshot':'source reviewed'} ${formatDate(p.checkedAt)}</small></span><div>${p.sources.map(source=>`<a href="${e(source.url)}" target="_blank" rel="noopener noreferrer">${e(source.label)} ↗</a>`).join('<br>')}</div></div>`).join('')+`<p class="workspace-hint">Showing ${Math.min(sourceLimit,programs.length).toLocaleString('en')} of ${programs.length.toLocaleString('en')} source records.</p>${sourceLimit<programs.length?'<button class="button secondary small" id="more-programme-sources">Show more source records</button>':''}`;
    $('#more-programme-sources')?.addEventListener('click',()=>{sourceLimit+=50;renderProgrammeSources();});
  };
  sourceDetails.ontoggle=()=>{if(sourceDetails.open)renderProgrammeSources();else{sourceRecords.replaceChildren();sourceLimit=50;}};
  $('#import-workspace').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('Backup too large');const restored=parseWorkspaceBackup(await file.text(),programs.map(p=>p.id));if(!confirm('Replace the current browser workspace with this backup?'))return;storage=restored;draft=null;persist();renderPage();toast('Workspace restored.');}catch{toast('This file is not a valid GradAtlas workspace backup.');}};
}
function detailContent(p){
  const a=assess(p,storage.profile),s=applicationStatus(p);
  if(detailTab==='requirements')return `<h2>Published requirements</h2><p>Check how these apply to your degree and applicant category.</p><ul>${p.requirements.map(r=>`<li>${e(r)}</li>`).join('')}</ul><h2>Grades in context</h2><p>${e(p.gradeNote)}</p><div class="callout ${a.key}"><strong>${e(a.label)}</strong>${a.details.length?`<ul>${a.details.map(d=>`<li>${e(d)}</li>`).join('')}</ul>`:'<p>Add your profile to compare your grade and language score against recorded requirements.</p>'}</div><button class="button secondary small" data-action="profile">${icon('user')}Edit my profile</button><h2>Check the original information</h2>${evidenceDisclosure(p)}${p.sources.map(s=>`<a class="source-link" href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.label)} ${icon('external')}</a>`).join('')}`;
  if(detailTab==='contact')return `<h2>Find the right conversation.</h2><p>Read the programme requirements before asking a question. For research enquiries, refer to a specific paper or project and check whether prior supervisor contact is expected.</p>${p.research?`<a class="source-link" href="${e(p.research.url)}" target="_blank" rel="noopener noreferrer">${e(p.research.label)} ${icon('external')}</a>`:''}${p.contact?`<div class="contact-block"><strong>${e(p.contact.name)}</strong><a href="mailto:${e(p.contact.email)}">${e(p.contact.email)}</a><small>Published contact · reviewed ${formatDate(p.checkedAt)}</small><a class="source-link" href="${e(p.contact.source)}" target="_blank" rel="noopener noreferrer">Verify contact on the official page ↗</a></div>`:`<div class="callout">A verified contact email has not been recorded. Use the programme’s official page to find the correct admissions or research contact.</div>`}<p>Published contact details do not indicate supervision availability. This catalogue does not yet contain a verified faculty directory or community reviews.</p><button class="button" style="margin-top:20px" data-studio="${p.id}">${icon('mail')}Draft a personal enquiry</button>`;
  if(detailTab==='notes')return `<h2>Your preparation checklist</h2><p>A general preparation guide. Follow the official programme’s exact document list.</p>${CHECKLIST.map((t,i)=>`<label class="checklist-label ${(storage.tasks[p.id]||[]).includes(i)?'done':''}"><input type="checkbox" data-task="${i}" ${(storage.tasks[p.id]||[]).includes(i)?'checked':''}><span>${e(t)}</span></label>`).join('')}<h2>Your notes</h2><textarea class="note-text" id="programme-note" maxlength="10000" aria-label="Personal programme notes" placeholder="Research ideas, questions for admissions, links to papers…">${e(storage.notes[p.id]||'')}</textarea><small class="note-save-status">${persistent?'Saved automatically in this browser.':'Browser storage unavailable; session only.'}</small>`;
  return `<h2>A closer look.</h2><p>${e(p.summary)}</p><div class="facts-grid"><div><span class="fact-label">STUDY FORMAT</span><span class="fact-value">${e(p.duration)} · ${p.mode}</span></div><div><span class="fact-label">LANGUAGE</span><span class="fact-value">${e(p.language)}</span></div><div><span class="fact-label">TUITION</span><span class="fact-value">${e(p.tuition.label)}</span></div><div><span class="fact-label">APPLICATION STATUS</span><span class="fact-value">${s.label}</span></div></div><h2>Application timeline</h2>${p.window?`<p>${formatDate(p.window.opens)} – ${formatDate(p.window.closes)}</p><p>${e(p.window.category)}</p><button class="button secondary small" style="margin-top:12px" data-calendar="${p.id}">${icon('calendar')}Download deadline reminder</button>`:`<p>Current application window not verified.</p>`}${p.scheduleNote?`<div class="callout">${e(p.scheduleNote)}</div>`:''}<p>Confirm the exact cutoff time, time zone and applicant category on the official page.</p><h2>Source & freshness</h2>${evidenceDisclosure(p)}<p>Reviewed ${formatDate(p.checkedAt)}${isStale(p)?' · Needs rechecking':''}. Recorded source information may change. Double-check current details on the official website before applying.</p>${p.dataNote?`<div class="callout">${e(p.dataNote)}</div>`:''}${p.sources.map(s=>`<a class="source-link" href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.label)} ${icon('external')}</a>`).join('')}`;
}
function openDetail(id,tab='overview'){
  const p=programs.find(p=>p.id===id);if(!p)return;detailId=id;detailTab=tab;
  const d=$('#detail-dialog');d.innerHTML=`<header class="detail-header"><button class="dialog-close" data-close="detail" aria-label="Close programme details">${icon('close')}</button><div class="uni-mark" aria-hidden="true">${icon('book')}</div><h1 id="detail-title">${e(p.title)}</h1><p>${e(p.university)}<br>${e(p.city)}, ${e(p.country)}</p>${p.registry?'<p class="workspace-hint">Registry-backed degree identity · admissions and current intake unreviewed</p>':''}<div class="detail-pills">${p.fields.map(f=>`<span class="tag">${e(f)}</span>`).join('')}</div></header><div class="detail-tabs" role="tablist" aria-label="Programme details">${[['overview','Overview'],['requirements','Requirements'],['contact','Research & contact'],['notes','My notes & checklist']].map(([id,label])=>`<button role="tab" id="detail-tab-${id}" data-detail-tab="${id}" aria-controls="detail-content" aria-selected="${tab===id}" tabindex="${tab===id?'0':'-1'}" class="${tab===id?'active':''}">${label}</button>`).join('')}</div><section class="detail-content" id="detail-content" role="tabpanel" aria-labelledby="detail-tab-${tab}">${detailContent(p)}</section><div class="detail-actions"><a class="button" href="${e(programmeRoute(p).url)}" target="_blank" rel="noopener noreferrer">${e(programmeRoute(p).label)} ${icon('external')}</a><button class="button secondary" data-save="${p.id}">${icon('bookmark')} ${storage.saved.includes(p.id)?'Saved':'Save'}</button></div>`;
  bindDetailNotes();if(!d.open)d.show();document.body.classList.add('detail-open');d.scrollTop=0;if(innerWidth<1100)setResults(false);if(page==='explore')map?.focus(p);d.querySelector('.dialog-close').focus({preventScroll:true});
}
function bindDetailNotes(){if($('#programme-note'))$('#programme-note').oninput=ev=>{storage.notes[detailId]=ev.target.value;persist();};}
function renderDetailTab(tab){detailTab=tab;document.querySelectorAll('[data-detail-tab]').forEach(b=>{const selected=b.dataset.detailTab===tab;b.classList.toggle('active',selected);b.setAttribute('aria-selected',selected);b.tabIndex=selected?0:-1;});$('#detail-content').setAttribute('aria-labelledby','detail-tab-'+tab);$('#detail-content').innerHTML=detailContent(programs.find(p=>p.id===detailId));bindDetailNotes();}
function openProfile(){const origin={id:detailId,tab:detailTab,open:$('#detail-dialog').open};const p=storage.profile||{name:'',degree:'',gpa:'',scale:'4',ielts:''};const d=$('#profile-dialog');d.innerHTML=`<button class="dialog-close" data-close="profile" aria-label="Close profile">${icon('close')}</button><p class="eyebrow">A LITTLE MORE PERSONAL</p><h1 id="profile-title">My profile</h1><p>Your profile is optional. Grades and IELTS highlight differences against recorded requirements in programme details and comparisons. Degree / field prefills enquiries; course prerequisites are not matched automatically. It does not determine admission.</p><div class="profile-storage"><strong>${persistent?'This browser only':'Session only · storage unavailable'}</strong>GradAtlas does not upload these answers. There is no account sync. Export a backup to move devices; clear your workspace before leaving a shared device.</div><form id="profile-form"><label class="form-field">Degree or field<input name="degree" maxlength="200" placeholder="e.g. Computer Engineering" value="${e(p.degree)}"></label><div class="form-grid"><label class="form-field">Current grade<input name="gpa" type="number" step="0.01" min="0" max="100" value="${e(p.gpa??'')}" placeholder="e.g. 2.82"></label><label class="form-field">Grading system<select name="scale">${[['4','0–4 · higher is better'],['5','0–5 · higher is better'],['10','0–10 · higher is better'],['100','0–100 · higher is better'],['german','German 1–4 · lower is better']].map(([value,text])=>`<option value="${value}" ${p.scale===value?'selected':''}>${text}</option>`).join('')}</select></label></div><label class="form-field">IELTS Academic overall · optional<input name="ielts" type="number" step="0.5" min="0" max="9" value="${e(p.ielts??'')}" placeholder="Leave blank if you have not taken IELTS"><span class="form-help">Component scores, other tests, exemptions and validity still need checking.</span></label><div class="callout">Grades are only compared within the same grading system. No acceptance probability or automatic international grade conversion is calculated.</div><div class="profile-footer"><button type="button" class="text-link" data-action="clear-profile">Clear profile</button><button class="button" type="submit">Save my profile ${icon('check')}</button></div></form><p class="workspace-hint" style="margin-bottom:0">Stored in this browser. You can export or delete it at any time.</p>`;
  const form=$('#profile-form');const grade=form.elements.gpa;const setLimits=()=>{const scale=form.elements.scale.value;grade.min=scale==='german'?'1':'0';grade.max=scale==='german'?'4':scale;};form.elements.scale.onchange=setLimits;setLimits();form.onsubmit=ev=>{ev.preventDefault();storage.profile={...Object.fromEntries(new FormData(form)),name:''};const saved=persist();d.close();renderPage();syncFilters();updateResults();if(origin.open){if(origin.id?.startsWith("ror-"))openInstitution(origin.id);else openDetail(origin.id,origin.tab);}toast(saved?'Profile saved in this browser.':'Profile kept for this session.');};d.showModal();}
function toggleSave(id){const had=storage.saved.includes(id);storage.saved=had?storage.saved.filter(v=>v!==id):[...storage.saved,id];persist();navigation();if(page==='explore')updateResults();if(page==='shortlist')renderShortlist();if($('#detail-dialog').open){const b=$('#detail-dialog [data-save]');b.innerHTML=icon('bookmark')+' '+(had?'Save':'Saved');}toast(had?'Removed from your shortlist.':'Saved to your shortlist.');}
function toggleCompare(id,add){if(add&&storage.compare.length>=3){toast('Choose up to three programmes. Remove one to add another.');document.querySelectorAll(`[data-compare="${id}"]`).forEach(c=>c.checked=false);return;}storage.compare=add?[...new Set([...storage.compare,id])]:storage.compare.filter(v=>v!==id);persist();navigation();tray();if(page==='compare')renderCompare();}
document.addEventListener('click',async ev=>{
  if(!ev.target.closest('.floating-panel,[data-action="toggle-menu"],[data-action="toggle-filters"]'))setPopover('',false);
  const b=ev.target.closest('button,a[data-nav]');if(!b)return;
  if(b.dataset.action==='toggle-menu'){setPopover('workspace-menu',$('#workspace-menu').hidden);return;}
  if(b.dataset.action==='toggle-filters'){setPopover('filter-panel',$('#filter-panel').hidden);return;}
  if(['browse','show-results'].includes(b.dataset.action)){clusterIds=null;setPopover('',false);resultsOpen=true;if(page==='explore')setResults(true);else location.hash='explore';return;}
  if(b.dataset.action==='map-help'){setPopover('',false);toast('Drag or use two fingers to move. Pinch or Ctrl + scroll to zoom. Shift + drag to rotate.');return;}
  if(b.dataset.action==='toggle-results'){setResults(!resultsOpen);return;}
  if(b.dataset.action==='reset'){clusterIds=null;Object.assign(filters,{query:'',field:'',country:'',open:false,free:false,fit:''});syncFilters();updateResults();return;}
  if(b.dataset.nav){rememberStudio();setPopover('',false);if(b.dataset.nav==='explore'){resultsOpen=false;if(page==='explore')setResults(false);else location.hash='explore';}else location.hash=b.dataset.nav;return;}
  if(b.dataset.studioTab){rememberStudio();studioTab=b.dataset.studioTab;renderWorkspace();return;}
  if(b.dataset.institution){openInstitution(b.dataset.institution);return;}
  if(b.dataset.action==='open-directory'){location.hash='explore';await setCatalogueMode('institutions');setResults(true);return;}
  if(b.dataset.detail){openDetail(b.dataset.detail,b.dataset.tab);return;}
  if(b.dataset.save){toggleSave(b.dataset.save);return;}
  if(b.dataset.filter){setResults(true);filters[b.dataset.filter]=!filters[b.dataset.filter];syncFilters();updateResults();return;}
  if(b.dataset.quick){setResults(true);filters.field=filters.field===b.dataset.quick?'':b.dataset.quick;syncFilters();updateResults();return;}

  if(b.dataset.close){$('#'+b.dataset.close+'-dialog').close();return;}
  if(b.dataset.detailTab){renderDetailTab(b.dataset.detailTab);return;}
  if(b.dataset.studio){const p=programs.find(p=>p.id===b.dataset.studio);studioId=p.id;studioTab='enquiry';draft=null;$('#detail-dialog').close();if(page==='workspace')renderWorkspace();else location.hash='workspace';return;}
  if(b.dataset.calendar){const p=programs.find(p=>p.id===b.dataset.calendar);download(p.id+'-deadline.ics',calendarEvent(p),'text/calendar');return;}
  if(b.dataset.removeCompare){toggleCompare(b.dataset.removeCompare,false);return;}
  switch(b.dataset.action){
    case 'reload':location.reload();break;
    case 'profile':setPopover('',false);openProfile();break;
    case 'clear-profile':storage.profile=null;filters.fit='';persist();$('#profile-dialog').close();renderPage();syncFilters();updateResults();toast('Profile cleared.');break;
    case 'clear-compare':storage.compare=[];persist();renderPage();break;
    case 'copy-email':try{await navigator.clipboard.writeText('Subject: '+$('#email-subject').value+'\n\n'+$('#email-draft').value);toast('Draft copied.');}catch{$('#email-draft').focus();$('#email-draft').select();toast('Select and copy the draft from the text box.');}break;
    case 'download-email':download('gradatlas-enquiry.txt','Subject: '+$('#email-subject').value+'\n\n'+$('#email-draft').value);break;
    case 'open-email':if(validRecipient())location.href=`mailto:${encodeURIComponent($('#email-form').elements.recipientEmail.value.trim())}?subject=${encodeURIComponent($('#email-subject').value)}&body=${encodeURIComponent($('#email-draft').value)}`;break;
    case 'save-draft':rememberStudio();storage.drafts[draft.id]={subject:draft.subject,body:draft.body,purpose:draft.fields.purpose||'admissions',recipientEmail:draft.fields.recipientEmail||'',fields:draft.fields};const saved=persist();updateDraftReview();toast(saved?'Draft saved in this browser.':'Draft kept for this session; browser storage is unavailable.');break;
    case 'download-plan':{const p=studioProgramme(),done=storage.tasks[p.id]||[];download(p.id+'-preparation.txt',`${p.title}\n${p.university} — ${p.country}\n\nPREPARATION PROMPTS\nFollow the programme’s own requirements.\n${CHECKLIST.map((t,i)=>(done.includes(i)?'[x] ':'[ ] ')+t).join('\n')}\n\nRECORDED REQUIREMENTS\n${p.requirements.join('\n')}\nGrades: ${p.gradeNote}\nTuition: ${p.tuition.label}\nDates: ${p.window?p.window.opens+' – '+p.window.closes+' · '+p.window.category:'Not verified'}\n\nYOUR NOTES\n${storage.notes[p.id]||''}\n\nOFFICIAL SOURCES\n${p.sources.map(s=>s.label+': '+s.url).join('\n')}\n\nReviewed: ${p.checkedAt}\nConfirm current applicant-specific instructions before submitting.`);break;}
    case 'export-workspace':b.disabled=true;try{download('gradatlas-workspace.xlsx',await workspaceWorkbook(programs,storage,{registry:registryManifest,locations:institutionManifest}),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast('Workspace Excel downloaded. It contains your personal notes and saved drafts.');}catch{toast('Workspace Excel could not complete. Reload and try again.');}finally{b.disabled=false;}break;
    case 'export-recovery':download('gradatlas-workspace.json',JSON.stringify({version:2,exportedAt:new Date().toISOString(),workspace:storage},null,2),'application/json');break;
    case 'catalogue':try{download('gradatlas-programmes.json',JSON.stringify(programmeExport(programs,registryManifest,institutionManifest),null,2),'application/json');}catch{toast('Catalogue provenance could not load. Reload before exporting.');}break;
    case 'export-institutions':b.disabled=true;try{const records=await loadInstitutionIndex();download('gradatlas-institution-directory.json',JSON.stringify(institutionExport(records,institutionManifest)), 'application/json');toast('Directory downloaded with source and licence information.');}catch{toast('The directory export could not complete. Please try again.');}finally{b.disabled=false;}break;
    case 'delete-data':if(confirm('Delete your profile, shortlist, comparisons, notes, checklists and saved drafts from this browser? This cannot be undone without an exported backup.')){storage=defaults();persist();draft=null;renderPage();toast('Local workspace deleted.');}break;
    case 'download-compare':{b.disabled=true;try{const list=storage.compare.map(id=>programs.find(p=>p.id===id)).filter(Boolean);download('gradatlas-comparison.xlsx',await comparisonWorkbook(list,storage.profile,{registry:registryManifest,locations:institutionManifest}),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast('Excel comparison downloaded.');}catch{toast('Excel export could not complete. Please try again.');}finally{b.disabled=false;}break;}
  }
});
document.addEventListener('change',ev=>{const el=ev.target;if(el.dataset.studioTask){const p=studioProgramme(),n=Number(el.dataset.studioTask),tasks=storage.tasks[p.id]||[];storage.tasks[p.id]=el.checked?[...new Set([...tasks,n])]:tasks.filter(i=>i!==n);persist();el.closest('label').classList.toggle('done',el.checked);$('#studio-content .studio-section-heading>span').textContent=storage.tasks[p.id].length+' / '+CHECKLIST.length;return;}if(el.dataset.compare)toggleCompare(el.dataset.compare,el.checked);if(el.dataset.track){storage.tracking[el.dataset.track]=el.value;persist();}if(el.dataset.task){const id=detailId,n=Number(el.dataset.task),tasks=storage.tasks[id]||[];storage.tasks[id]=el.checked?[...new Set([...tasks,n])]:tasks.filter(x=>x!==n);el.closest('label').classList.toggle('done',el.checked);persist();if(page==='shortlist')renderShortlist();}});
document.addEventListener('keydown',ev=>{const studio=ev.target.closest('[data-studio-tab][role=tab]');if(studio&&['ArrowLeft','ArrowRight','Home','End'].includes(ev.key)){ev.preventDefault();const choices=['preparation','enquiry','guides'];let i=choices.indexOf(studio.dataset.studioTab);i=ev.key==='Home'?0:ev.key==='End'?2:(i+(ev.key==='ArrowRight'?1:-1)+3)%3;rememberStudio();studioTab=choices[i];renderWorkspace();document.querySelector(`[data-studio-tab="${studioTab}"][role=tab]`).focus();return;}if(ev.key==='Escape'&&!$('#profile-dialog').open){if(!$('#workspace-menu').hidden||!$('#filter-panel')?.hidden){const trigger=!$('#workspace-menu').hidden?$('.menu-trigger'):$('.filter-trigger');setPopover('',false);trigger?.focus();}else if($('#detail-dialog').open)$('#detail-dialog').close();else if(["shortlist","compare"].includes(page)){location.hash="explore";}else setResults(false);}if(ev.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#detail-dialog').open&&!$('#profile-dialog').open){ev.preventDefault();$('#search')?.focus();}const tab=ev.target.closest('[data-detail-tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(ev.key)){ev.preventDefault();const tabs=[...document.querySelectorAll('[data-detail-tab]')];let i=tabs.indexOf(tab);i=ev.key==='Home'?0:ev.key==='End'?tabs.length-1:(i+(ev.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;renderDetailTab(tabs[i].dataset.detailTab);tabs[i].focus();}});
window.addEventListener('hashchange',()=>{if(!programs.length)return;renderPage();window.scrollTo({top:0,behavior:'instant'});});
for(const id of ['detail-dialog','profile-dialog'])$('#'+id).addEventListener('click',ev=>{if(ev.target===$('#'+id)){const r=ev.target.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)ev.target.close();}});
$('#detail-dialog').addEventListener('close',()=>{document.body.classList.remove('detail-open');});
$('.skip-link').onclick=ev=>{ev.preventDefault();$('#main').focus();$('#main').scrollIntoView();};
try {const response=await fetch('data/programs.json');if(!response.ok)throw Error('Catalogue unavailable');programs=await response.json();try{const guides=await fetch('data/guidance.json');if(guides.ok)guidance=await guides.json();const manifest=await fetch('data/institution-manifest.json');if(manifest.ok)institutionManifest=await manifest.json();const registry=await fetch('data/programme-registry-manifest.json');if(registry.ok)registryManifest=await registry.json();}catch{}storage.saved=storage.saved.filter(id=>programs.some(p=>p.id===id));storage.compare=storage.compare.filter(id=>programs.some(p=>p.id===id)).slice(0,3);renderPage();$('.menu-trigger').disabled=false;if(recoveredWorkspace)toast('The saved workspace could not be read. Import a backup to restore it.');}catch{$('#screen').innerHTML=empty('The atlas could not load.','Please reload the page. Your saved browser workspace has not been deleted.','explore','Reload the atlas');$('#screen [data-nav]').removeAttribute('data-nav');$('#screen button').dataset.action='reload';}
